insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A habilitação para conduzir veículo automotor é apurada por meio de exames realizados no órgão ou entidade executivos do Estado ou do Distrito Federal do domicílio ou residência do candidato, ou na sede estadual ou distrital do próprio órgão. O candidato deve ser penalmente imputável, saber ler e escrever e possuir Carteira de Identidade ou equivalente. As informações do candidato são cadastradas no Renach.', '["Exames no órgão estadual ou distrital.","Imputável, alfabetizado e com identidade.","Cadastro no Renach."]'::jsonb, '["Requisitos: imputabilidade penal, saber ler e escrever, identidade."]'::jsonb, 'O candidato maior de dezoito anos, alfabetizado e com identidade pode se habilitar.', '["Assertiva que dispensa saber ler e escrever para a habilitação erra."]'::jsonb, '[{"termo":"Renach","significado":"Registro Nacional de Carteiras de Habilitação."}]'::jsonb, '["Art. 141"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-140' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c22f74d5b2159a52f14d2ff9402d5e7fd075af01956bb82b2531bb601c94275b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo de habilitação e as normas relativas à aprendizagem para conduzir veículos automotores e à autorização para conduzir ciclomotores são regulamentados pelo Contran. A autorização para conduzir veículos de propulsão humana e de tração animal fica a cargo dos Municípios.', '["Regulamentação pelo Contran.","Municípios autorizam propulsão humana e tração animal."]'::jsonb, '["Municípios, não os Detrans, autorizam condutores de tração animal."]'::jsonb, 'O Contran regula as aulas e o processo de habilitação.', '["Assertiva que atribui ao Detran a autorização de condutores de tração animal erra."]'::jsonb, '[]'::jsonb, '["Art. 140"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-141' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '48e85e73bb083fac665a7209bc053738d817d576eeadeec839509dd6ddd96432'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O reconhecimento de habilitação obtida em outro país está subordinado às condições estabelecidas em convenções e acordos internacionais e às normas do Contran.', '["Reconhecimento conforme tratados e normas do Contran."]'::jsonb, '["Depende de convenções e acordos internacionais."]'::jsonb, 'A CNH estrangeira é reconhecida nos termos do acordo internacional.', '["Assertiva que reconhece automaticamente qualquer habilitação estrangeira erra."]'::jsonb, '[]'::jsonb, '["Art. 118"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-142' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '785099bb9e6c7afa5d5cd00ba700db763ec1dedda7631506612fcef080c6465a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os candidatos podem habilitar-se nas categorias A a E. A categoria A é de veículo motorizado de duas ou três rodas; B, de veículo cujo peso bruto total não exceda 3.500 kg e a lotação oito lugares, excluído o motorista; C, de veículos da B e de carga com peso bruto total acima de 3.500 kg; D, de veículos das B e C e de transporte de passageiros com lotação acima de oito lugares; E, de combinações em que a unidade acoplada tenha 6.000 kg ou mais de peso bruto total ou lotação acima de oito lugares. Para a categoria C exige-se um ano de categoria B e não mais de uma infração gravíssima nos últimos doze meses. A categoria B também autoriza motor-casa até 6.000 kg e veículos elétricos ou híbridos até 4.250 kg.', '["Categorias A a E em gradação.","Limites de 3.500 kg e de oito lugares.","C exige um ano de B.","B autoriza motor-casa e veículos elétricos ou híbridos nos limites legais."]'::jsonb, '["ATUALIZAÇÃO: limites da categoria C e extensões da B foram alterados por leis recentes.","Categoria B: até 3.500 kg e oito lugares."]'::jsonb, 'Quem tem categoria B há um ano e sem reincidência grave pode pedir a categoria C.', '["Assertiva que fixa em 3.000 kg o limite de peso da categoria B erra: são 3.500 kg."]'::jsonb, '[]'::jsonb, '["Art. 145"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-143' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '11042b00ee2fcef092c53f92ff97abc2a4de562a0b129b92b6a34d49160c7898'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trator de roda, o trator de esteira, o trator misto ou o equipamento automotor destinado à movimentação de cargas ou execução de trabalho agrícola, de terraplenagem, construção ou pavimentação só podem ser conduzidos na via pública por condutor habilitado nas categorias C, D ou E. O trator de roda e os equipamentos para trabalhos agrícolas podem também ser conduzidos por condutor da categoria B.', '["Categorias C, D ou E.","Exceção: trator de roda e equipamentos agrícolas com categoria B."]'::jsonb, '["Exceção só para tratores de roda e equipamentos agrícolas."]'::jsonb, 'O agricultor com categoria B conduz trator de roda na via.', '["Assertiva que permite a categoria B para conduzir trator de esteira na via erra."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-144' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '18bdc984152fb4f0b47f5fc12dd5b2642e6c7ffd5e8aa0bde36169c9f3e04882'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para habilitar-se nas categorias D e E ou para conduzir veículo de transporte coletivo de passageiros, de escolares, de emergência ou de produto perigoso, o candidato deve ser maior de vinte e um anos; estar habilitado há, no mínimo, dois anos na categoria B ou um ano na categoria C, para a categoria D, e há um ano na categoria C, para a categoria E; não ter cometido mais de uma infração gravíssima nos últimos doze meses; e ser aprovado em curso especializado e em treinamento de prática veicular em situação de risco, nos termos do Contran.', '["Maior de vinte e um anos.","Tempo mínimo de habilitação prévia.","No máximo uma infração gravíssima em doze meses.","Curso especializado e treinamento em situação de risco."]'::jsonb, '["D: dois anos na B ou um ano na C; E: um ano na C.","ATUALIZAÇÃO: requisitos ajustados por leis recentes."]'::jsonb, 'Quem tem categoria B há dois anos pode buscar a categoria D, atendidos os demais requisitos.', '["Assertiva que fixa em dezoito anos a idade mínima para a categoria D erra: são mais de vinte e um anos."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-145' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '60ef69b65e47804fb249bfed21eba66368c7f88b7dd0351fc9a11c09db0905f2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Além do art. 145, para conduzir ambulâncias o candidato deve comprovar treinamento especializado e reciclagem em cursos específicos a cada cinco anos, nos termos da normatização do Contran.', '["Treinamento especializado.","Reciclagem a cada cinco anos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Reciclagem a cada cinco anos."]'::jsonb, 'O motorista de ambulância refaz o curso a cada cinco anos.', '["Assertiva que fixa em dois anos a reciclagem do condutor de ambulância erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 145"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-145-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1f0274f28b1cf2bcb513430be49c2322a606b3714c8fd8cb6e120d3667b0ba75'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para conduzir veículos de outra categoria, o condutor deve realizar os exames complementares exigidos para a habilitação na categoria pretendida.', '["Exames complementares para nova categoria."]'::jsonb, '["Exames complementares, não todo o processo."]'::jsonb, 'Quem tem categoria B faz exames complementares para a C.', '["Assertiva que dispensa novos exames para mudar de categoria erra."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-146' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ccaecae319f5aa5226ef195be09b16aa0dea3e78c41148f0c45df200eaa51dd1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O candidato à habilitação se submete a exames realizados pelo órgão executivo de trânsito, na ordem prevista: aptidão física e mental; escrito sobre legislação de trânsito; noções de primeiros socorros; e direção veicular na via pública. Os exames de aptidão física e mental e a avaliação psicológica são feitos por médicos e psicólogos peritos com titulação de especialista em medicina do tráfego e em psicologia do trânsito. O exame de aptidão física e mental é renovado a cada dez anos para condutores com menos de cinquenta anos, a cada cinco anos entre cinquenta e menos de setenta anos, e a cada três anos a partir de setenta anos. A avaliação psicológica se inclui no exame de quem exerce atividade remunerada ao veículo e, para os demais, apenas na primeira habilitação.', '["Ordem dos exames.","Peritos especialistas em medicina do tráfego e psicologia do trânsito.","Renovação em dez, cinco e três anos conforme a idade.","Avaliação psicológica para quem exerce atividade remunerada."]'::jsonb, '["Dez anos (menos de 50), cinco anos (50 a 69) e três anos (70 ou mais).","ATUALIZAÇÃO: periodicidade e titulação dos peritos foram alteradas por leis posteriores."]'::jsonb, 'O condutor de 55 anos renova o exame de aptidão física e mental a cada cinco anos.', '["Assertiva que fixa em cinco anos a renovação para condutores com menos de cinquenta anos erra: são dez anos."]'::jsonb, '[]'::jsonb, '["Art. 148"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-147' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cfa90ffa766810e7ad864dbaaf321ee7735745f859fe92f16b73c3a9847a23d9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao candidato com deficiência auditiva é assegurada acessibilidade de comunicação, mediante tecnologias assistivas ou ajudas técnicas, em todas as etapas da habilitação. O material didático audiovisual das aulas teóricas deve ser acessível, com legenda oculta e tradução simultânea em Libras. O candidato pode requerer, na inscrição, intérprete de Libras para aulas práticas e teóricas.', '["Acessibilidade de comunicação.","Material com legenda oculta e Libras.","Intérprete de Libras a pedido."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O candidato surdo requer intérprete de Libras nas aulas.', '["Assertiva que dispensa o intérprete de Libras nas aulas teóricas erra."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-147-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd7a5434a937e1da88f67a9c18fb2a9c7871ac65772dd237b6a6e96935bdca3d7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os exames de habilitação, exceto os de direção veicular, podem ser aplicados por entidades públicas ou privadas credenciadas pelo órgão executivo de trânsito. A formação de condutores inclui curso de direção defensiva e de conceitos básicos de proteção ao meio ambiente. Ao candidato aprovado é conferida Permissão para Dirigir, com validade de um ano. A CNH é conferida no término de um ano, desde que o condutor não tenha cometido infração grave ou gravíssima nem seja reincidente em infração média; caso contrário, reinicia todo o processo de habilitação. Os exames de aptidão física e mental e a avaliação psicológica são realizados por peritos autorizados pelo órgão máximo executivo da União.', '["Exames aplicados por entidades credenciadas, exceto direção veicular.","Permissão para Dirigir por um ano.","CNH definitiva sem infração grave, gravíssima ou média reincidente.","Reinício do processo em caso de não obtenção."]'::jsonb, '["Permissão para Dirigir: UM ano.","Infração grave ou gravíssima na permissão leva a refazer o processo."]'::jsonb, 'O novo condutor que comete infração grave no primeiro ano não obtém a CNH definitiva.', '["Assertiva que fixa em dois anos a validade da Permissão para Dirigir erra: é um ano."]'::jsonb, '[{"termo":"Permissão para Dirigir","significado":"Habilitação provisória válida por um ano."}]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-148' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd37fe1855aefdc56b8f5469b53bac122ddf97154f18ecccd217ee80aee394322'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os condutores das categorias C, D e E devem comprovar resultado negativo em exame toxicológico para obtenção e renovação da CNH. O exame busca aferir o consumo de substâncias psicoativas que comprometam a capacidade de direção e tem janela de detecção mínima de 90 dias. Os condutores dessas categorias com menos de 70 anos fazem novo exame a cada 2 anos e 6 meses. É garantido o direito de contraprova e de recurso administrativo sem efeito suspensivo. O resultado positivo no exame periódico acarreta a suspensão do direito de dirigir por três meses, condicionada a novo exame negativo. O exame é realizado em regime de livre concorrência por laboratórios credenciados. A não realização do exame impede a obtenção ou renovação da CNH e acarreta as sanções previstas.', '["Exame toxicológico para as categorias C, D e E.","Janela de detecção mínima de 90 dias.","Novo exame a cada 2 anos e 6 meses para menores de 70 anos.","Suspensão por três meses em caso de resultado positivo no periódico.","Livre concorrência entre laboratórios credenciados."]'::jsonb, '["ATUALIZAÇÃO: o exame toxicológico foi ampliado e alterado por leis posteriores; confira o texto vigente.","Resultado positivo no periódico: suspensão de TRÊS meses."]'::jsonb, 'O caminhoneiro de 45 anos refaz o exame toxicológico a cada 2 anos e 6 meses.', '["Assertiva que exige o exame toxicológico dos condutores da categoria B erra: aplica-se às categorias C, D e E."]'::jsonb, '[]'::jsonb, '["Art. 165-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-148-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e4e4d6e835fc3d3825768451e220c4674f9d43594a555f83c6fd1ec7895aa996'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao renovar os exames de habilitação, o condutor que não tenha curso de direção defensiva e de primeiros socorros deve a eles ser submetido, conforme normatização do Contran. A empresa que utiliza condutores contratados para operar sua frota é obrigada a fornecer curso de direção defensiva, primeiros socorros e outros, conforme o Contran.', '["Cursos exigidos na renovação, se o condutor não os tem.","Empresas fornecem cursos aos condutores contratados."]'::jsonb, '["Obrigação da EMPRESA que usa condutores contratados."]'::jsonb, 'A transportadora paga o curso de direção defensiva dos motoristas.', '["Assertiva que isenta a empresa de fornecer os cursos aos seus condutores erra."]'::jsonb, '[]'::jsonb, '["Art. 148"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-150' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b039b1db539001a1cdc96a119f18d8dd30ed4e443ff97eb52ba0f48bda7b643a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O exame de direção veicular é realizado perante comissão integrada por três membros designados pelo dirigente do órgão executivo local de trânsito, e pelo menos um deles deve ser habilitado em categoria igual ou superior à pretendida pelo candidato. Militares, policiais e bombeiros com curso de formação de condutor ministrado em suas corporações são dispensados dos exames em que tenham sido aprovados naquele curso, desde que observadas as normas do Contran, mediante requerimento instruído com ofício do comandante.', '["Comissão de três membros.","Pelo menos um com categoria igual ou superior.","Dispensa para militares e policiais com curso nas corporações."]'::jsonb, '["Comissão de TRÊS membros."]'::jsonb, 'A banca de direção tem três examinadores, um deles com a categoria pretendida.', '["Assertiva que fixa comissão de cinco membros erra: são três."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-152' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3f514f1dfd4b3360cee9904ee864fb7bf0c9538739153599434c121387f98b75'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O candidato habilitado tem em seu prontuário a identificação de seus instrutores e examinadores, que são passíveis de punição conforme regulamentação do Contran. As penalidades aplicadas a instrutores e examinadores são advertência, suspensão e cancelamento da autorização para o exercício da atividade, conforme a falta cometida.', '["Identificação de instrutores e examinadores no prontuário.","Advertência, suspensão e cancelamento."]'::jsonb, '["Três penalidades possíveis."]'::jsonb, 'O examinador que comete falta grave pode ter a autorização cancelada.', '["Assertiva que isenta examinadores e instrutores de penalidades erra."]'::jsonb, '[]'::jsonb, '["Art. 156"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-153' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2c882bf0db979fa6a18ab2ad520ef58cabf5655322fc3e0e9ca573235bdf6039'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos destinados à formação de condutores são identificados por uma faixa amarela de vinte centímetros de largura, pintada ao longo da carroçaria, à meia altura, com a inscrição AUTO-ESCOLA em preto. No veículo eventualmente utilizado para aprendizagem, afixa-se faixa branca removível de mesma largura. As idades máximas dos veículos de formação, sem computar o ano de fabricação, são oito anos para a categoria A, doze anos para a B e vinte anos para as categorias C, D e E.', '["Faixa amarela de vinte centímetros com AUTO-ESCOLA.","Faixa branca removível para uso eventual.","Idades máximas: oito, doze e vinte anos."]'::jsonb, '["Idades máximas: A, oito anos; B, doze anos; C, D e E, vinte anos.","Faixa de vinte centímetros (a do escolar tem quarenta)."]'::jsonb, 'O carro da autoescola tem faixa amarela e no máximo doze anos de uso.', '["Assertiva que fixa em dez anos a idade máxima do veículo da categoria B erra: são doze anos."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-154' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '67815e3fc213009e2468a5ba3d72aa7f1b76d7c771be34617c5e677d49fe0ef0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A formação de condutor de veículo automotor é realizada por instrutor autorizado pelo órgão executivo de trânsito dos Estados ou do Distrito Federal, pertencente ou não à entidade credenciada. Ao aprendiz é expedida autorização para aprendizagem, conforme o Contran, após aprovação nos exames de aptidão física e mental, de primeiros socorros e sobre legislação de trânsito.', '["Instrutor autorizado pelo órgão estadual ou distrital.","Autorização para aprendizagem após aprovação nos exames."]'::jsonb, '["Instrutor pode ou não pertencer a entidade credenciada.","ATUALIZAÇÃO: o processo de formação foi flexibilizado por normas recentes do Contran; confira a regulamentação vigente."]'::jsonb, 'O aprendiz recebe a autorização para aprender depois dos exames iniciais.', '["Assertiva que exige que o instrutor pertença a autoescola erra: pode ou não pertencer."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-155' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8381484bcf0f00d48f1fe3a84ed431f56f0ad8bb2cb157e3f5333766518f6f93'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran regulamenta o credenciamento para prestação de serviço pelas autoescolas e outras entidades destinadas à formação de condutores e as exigências para o exercício das atividades de instrutor e examinador.', '["Credenciamento regulamentado pelo Contran.","Exigências para instrutores e examinadores."]'::jsonb, '["Competência do Contran."]'::jsonb, 'O Contran define como as autoescolas são credenciadas.', '["Assertiva que atribui ao município o credenciamento das autoescolas erra."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-156' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6383a44bf6abbcf2146a907247a7728e16f53cf66bb4a531c36a94af8f98cab2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
