insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A aprendizagem só pode realizar-se nos termos, horários e locais estabelecidos pelo órgão executivo de trânsito e com o aprendiz acompanhado por instrutor autorizado. Além do aprendiz e do instrutor, o veículo utilizado na aprendizagem pode conduzir apenas mais um acompanhante.', '["Termos, horários e locais definidos pelo órgão de trânsito.","Acompanhamento por instrutor.","Apenas mais um acompanhante."]'::jsonb, '["Além do instrutor, só mais UM acompanhante."]'::jsonb, 'Na aula prática vão o aprendiz, o instrutor e um único acompanhante.', '["Assertiva que permite dois acompanhantes além do instrutor erra: apenas um."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-158' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6cb0eae481ba5dfe1c05dde9375804bfbfc05267f41729bf70b300bc1c1f806b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
