on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira Nacional de Habilitação pode ser emitida em meio físico ou digital, a critério do candidato ou do condutor; deve conter fotografia, nome, número do CPF e demais requisitos do Contran; e tem fé pública e equivale a documento de identidade no território nacional. É obrigatório o porte da Permissão para Dirigir ou da CNH quando o condutor estiver à direção, dispensado se for possível verificar a habilitação no sistema. Só tem validade quando apresentada em original. A renovação ou nova via só é feita após quitação dos débitos do prontuário, e a validade da CNH está condicionada à vigência do exame de aptidão física e mental. Os órgãos enviam aviso de vencimento com trinta dias de antecedência.', '["CNH física ou digital, com fé pública e valor de identidade.","Porte obrigatório, com dispensa se houver consulta ao sistema.","Validade só em original.","Renovação após quitação de débitos.","Aviso de vencimento com trinta dias de antecedência."]'::jsonb, '["ATUALIZAÇÃO: CNH digital e dispensa do porte vieram de leis posteriores.","Validade da CNH vinculada ao exame de aptidão física e mental."]'::jsonb, 'O condutor apresenta a CNH digital ou o agente consulta o sistema.', '["Assertiva que torna válida a cópia autenticada da CNH erra: só vale o original."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-159' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0e2b133ef94342e1e5b920f34bc666a77bfd2c7e79fc5892a76c3444360518e0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor condenado por delito de trânsito deve ser submetido a novos exames para voltar a dirigir, conforme as normas do Contran, independentemente do reconhecimento da prescrição em face da pena concretizada na sentença. Em caso de sinistro grave, o condutor envolvido pode ser submetido aos exames, a juízo da autoridade executiva estadual de trânsito, assegurada ampla defesa, e esta pode apreender o documento de habilitação até a aprovação nos exames.', '["Novos exames após condenação por delito de trânsito.","Independe da prescrição.","Sinistro grave: exames a juízo da autoridade, com ampla defesa.","Apreensão do documento até a aprovação."]'::jsonb, '["Exames exigidos mesmo com prescrição."]'::jsonb, 'O condutor condenado por homicídio culposo no trânsito refaz os exames para voltar a dirigir.', '["Assertiva que dispensa os exames se houver prescrição da pena erra."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-160' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cd3b20084d9ab66ab36929465fa2be923d9b9e45ab5ce767ca6186dc25650590'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui infração de trânsito a inobservância de qualquer preceito do Código ou da legislação complementar, e o infrator sujeita-se às penalidades e medidas administrativas indicadas em cada artigo do capítulo e às punições do capítulo dos crimes de trânsito.', '["Infração = inobservância do Código ou da legislação complementar.","Penalidades e medidas administrativas de cada artigo."]'::jsonb, '["Infração administrativa e crime são esferas distintas."]'::jsonb, 'Quem descumpre uma regra do Código comete infração de trânsito.', '["Assertiva que restringe as infrações às hipóteses do capítulo específico erra."]'::jsonb, '[]'::jsonb, '["Art. 256"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-161' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '62897d91109ea2b294a627c767768fe89ebbe3f1251e9178aaedda6edf91b58b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dirigir veículo sem possuir CNH, Permissão para Dirigir ou Autorização para Conduzir Ciclomotor é infração gravíssima, com multa (três vezes) e retenção do veículo até a apresentação de condutor habilitado. Dirigir com habilitação cassada ou com suspensão do direito de dirigir também é gravíssima, com multa (três vezes), recolhimento do documento e retenção do veículo. Dirigir com habilitação de categoria diferente é gravíssima, com multa (duas vezes) e retenção. Também é gravíssima dirigir com CNH vencida há mais de trinta dias, sem lentes corretoras, aparelho auxiliar de audição ou adaptações impostas, ou sem os cursos especializados obrigatórios, com multa e retenção do veículo.', '["Sem habilitação: gravíssima, multa três vezes.","Habilitação cassada ou suspensa: gravíssima, multa três vezes.","Categoria diferente: gravíssima, multa duas vezes.","CNH vencida há mais de trinta dias: gravíssima.","Sem lentes corretoras ou adaptações impostas: gravíssima."]'::jsonb, '["Sem habilitação e cassada/suspensa: multa TRÊS vezes.","Categoria diferente: multa DUAS vezes.","ATUALIZAÇÃO: a CNH vencida há mais de trinta dias passou a ser gravíssima por lei posterior."]'::jsonb, 'Quem dirige sem CNH sofre multa de três vezes e retenção do veículo.', '["Assertiva que classifica como média a direção com CNH de categoria diferente erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-162' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ba0e9947e79b7b901e315d62c77372d5b006a1b0f05623667f2a66b5efc3fa9a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Entregar a direção do veículo a pessoa nas condições previstas no artigo anterior é infração com as mesmas características e penalidades do artigo 162, com a medida administrativa de retenção do veículo até a apresentação de condutor habilitado.', '["Mesmas infração e penalidades do art. 162.","Retenção do veículo."]'::jsonb, '["Quem entrega a direção sofre as mesmas penalidades."]'::jsonb, 'O proprietário que entrega o carro a quem não tem CNH é autuado.', '["Assertiva que isenta o proprietário que entrega a direção a quem não é habilitado erra."]'::jsonb, '[]'::jsonb, '["Art. 162"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-163' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4825b8edb81526011b35fb402ecad4926f50c04426b9f287fe2f8128bb421d2e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Permitir que pessoa nas condições do art. 162 tome posse do veículo automotor e passe a conduzi-lo na via é infração com as mesmas características e penalidades do art. 162, com a medida administrativa do inciso III do art. 162.', '["Mesmas infração e penalidades do art. 162.","Retenção do veículo."]'::jsonb, '["Quem permite a posse também responde."]'::jsonb, 'O dono que deixa o carro com quem não tem CNH é autuado.', '["Assertiva que isenta quem permite a posse do veículo a não habilitado erra."]'::jsonb, '[]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-164' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0b8ada8f6f8e0b24613be390a4c220a04f1f67d8705732f94973e19a048bbdd4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dirigir sob a influência de álcool ou de qualquer outra substância psicoativa que determine dependência é infração gravíssima, com multa (dez vezes) e suspensão do direito de dirigir por doze meses, além de recolhimento do documento de habilitação e retenção do veículo. A multa é aplicada em dobro em caso de reincidência no período de até doze meses.', '["Infração gravíssima.","Multa (dez vezes) e suspensão por doze meses.","Recolhimento da CNH e retenção do veículo.","Dobro da multa na reincidência em até doze meses."]'::jsonb, '["Multa DEZ vezes e suspensão de DOZE meses.","Reincidência em até doze meses: multa em dobro.","Pode também configurar crime de embriaguez ao volante."]'::jsonb, 'O condutor flagrado alcoolizado paga multa de dez vezes e fica doze meses sem dirigir.', '["Assertiva que fixa em seis meses a suspensão do direito de dirigir erra: são doze meses."]'::jsonb, '[]'::jsonb, '["Art. 277"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-165' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '238a836737c45fcc9241340f7d1286d0af11b61e499b3411bd16e4b99d907878'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recusar-se a ser submetido a teste, exame clínico, perícia ou outro procedimento que permita certificar influência de álcool ou outra substância psicoativa, na forma do art. 277, é infração gravíssima, com multa (dez vezes) e suspensão do direito de dirigir por doze meses, recolhimento do documento e retenção do veículo. A multa é aplicada em dobro na reincidência em até doze meses.', '["Recusa ao teste do bafômetro ou perícia.","Mesmas penalidades da direção sob influência de álcool.","Dobro da multa na reincidência."]'::jsonb, '["ATUALIZAÇÃO: infração incluída por lei posterior.","A recusa recebe as mesmas penalidades do art. 165."]'::jsonb, 'Quem se recusa ao bafômetro sofre a mesma penalidade de quem dirigiu alcoolizado.', '["Assertiva que isenta de penalidade administrativa quem se recusa ao bafômetro erra."]'::jsonb, '[]'::jsonb, '["Art. 165"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-165-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5917a0db101b8c152c258026d85520a6cf5e32b9e94aabd1c3dbc947cdb0ccf8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dirigir veículo sem realizar o exame toxicológico previsto no art. 148-A é infração gravíssima, com multa (cinco vezes) e, em caso de reincidência em até doze meses, multa (dez vezes) e suspensão do direito de dirigir. Se o condutor deixar de fazer o exame periódico, a infração se configura quando dirigir após o trigésimo dia do vencimento do prazo.', '["Infração gravíssima.","Multa (cinco vezes), dez vezes na reincidência.","Suspensão na reincidência.","Prazo de trinta dias após o vencimento do exame periódico."]'::jsonb, '["ATUALIZAÇÃO: infração incluída pela lei do exame toxicológico.","Multa CINCO vezes; reincidência em até doze meses: dez vezes e suspensão."]'::jsonb, 'O motorista de ônibus sem exame toxicológico na renovação é autuado.', '["Assertiva que isenta de multa a falta do exame toxicológico erra."]'::jsonb, '[]'::jsonb, '["Art. 148-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-165-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'da862eaf56c76d36330f7a4dd9dad9539b3fee61f90683bd16f7b21465a76af6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dirigir veículo tendo obtido resultado positivo no exame toxicológico previsto no caput do art. 148-A é infração gravíssima, com multa (cinco vezes) e, em caso de reincidência em até doze meses, multa (dez vezes) e suspensão do direito de dirigir.', '["Infração gravíssima.","Multa (cinco vezes), dez vezes na reincidência, com suspensão."]'::jsonb, '["ATUALIZAÇÃO: infração incluída pela lei do exame toxicológico."]'::jsonb, 'O motorista com resultado positivo que continua dirigindo é autuado.', '["Assertiva que fixa multa de dez vezes na primeira ocorrência erra: são cinco vezes."]'::jsonb, '[]'::jsonb, '["Art. 148-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-165-c' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '039c5d35c7a8647044bfa56333dbc5047f955e1d7355401d166b086016aba96f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de realizar o exame toxicológico periódico do §2º do art. 148-A, após trinta dias do vencimento do prazo, é infração gravíssima, com multa (cinco vezes). A competência para aplicar a penalidade é do órgão de trânsito de registro da CNH do infrator.', '["Infração gravíssima.","Multa (cinco vezes).","Competência do órgão de registro da CNH."]'::jsonb, '["Trinta dias após o vencimento do prazo.","ATUALIZAÇÃO: infração incluída pela lei do exame toxicológico."]'::jsonb, 'O condutor que passa trinta dias do prazo sem refazer o exame é multado.', '["Assertiva que atribui a competência ao órgão do local da infração erra: é o órgão de registro da CNH."]'::jsonb, '[]'::jsonb, '["Art. 165-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-165-d' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd20d02b7437abcf73dadda818ebcffe14fd5a4a2fdac9ddd3a62b7f7af9d32c0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Confiar ou entregar a direção de veículo a pessoa que, mesmo habilitada, por seu estado físico ou psíquico, não estiver em condições de dirigi-lo com segurança é infração gravíssima, com penalidade de multa.', '["Infração gravíssima.","Penalidade de multa."]'::jsonb, '["Alcança pessoa HABILITADA, mas sem condições físicas ou psíquicas."]'::jsonb, 'Quem entrega o carro a um amigo embriagado, ainda que habilitado, comete a infração.', '["Assertiva que limita a infração à entrega do veículo a não habilitado erra."]'::jsonb, '[]'::jsonb, '["Art. 162"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-166' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8586fb8aa2d79dc042f2ca0ad205401d4b3cb39a386a67f24c2df58ed10d12b8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
