insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transportar crianças em veículo automotor sem observância das normas de segurança especiais estabelecidas no Código é infração gravíssima, com multa e a medida administrativa de retenção do veículo até que a irregularidade seja sanada.', '["Infração gravíssima.","Multa e retenção do veículo."]'::jsonb, '["Gravíssima; o veículo fica retido até regularizar."]'::jsonb, 'A criança de seis anos sem cadeirinha adequada gera a autuação.', '["Assertiva que classifica como grave o transporte irregular de crianças erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-168' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a28ffad920e4d3f48d3858d6f7abfe872c42c7f680ff121124a2b693a45d6256'
