insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Usar o veículo para arremessar, sobre os pedestres ou veículos, água ou detritos é infração média, com penalidade de multa.', '["Infração média.","Multa."]'::jsonb, '["Infração MÉDIA."]'::jsonb, 'Passar sobre a poça de propósito para molhar o pedestre é infração.', '["Assertiva que classifica como leve o arremesso de água sobre pedestres erra: é média."]'::jsonb, '[]'::jsonb, '["Art. 172"]'::jsonb, 'under_review', 'claude'
