select u.id, u.content_sha256, 'Atirar do veículo ou abandonar na via objetos ou substâncias é infração média, com penalidade de multa.', '["Infração média.","Multa."]'::jsonb, '["Média, como o arremesso de água ou detritos."]'::jsonb, 'Jogar lixo pela janela do carro gera multa.', '["Assertiva que classifica como gravíssima a conduta de atirar objetos do veículo erra: é média."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
