insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Disputar corrida é infração gravíssima, com multa (dez vezes), suspensão do direito de dirigir e apreensão do veículo, e medida administrativa de recolhimento do documento de habilitação e remoção do veículo. A multa é aplicada em dobro na reincidência no período de doze meses.', '["Infração gravíssima.","Multa (dez vezes), suspensão e apreensão do veículo.","Dobro da multa na reincidência em doze meses."]'::jsonb, '["Pode configurar também o crime de racha."]'::jsonb, 'O racha na avenida gera suspensão da CNH e apreensão do veículo.', '["Assertiva que prevê apenas multa para quem disputa corrida erra."]'::jsonb, '[]'::jsonb, '["Art. 308"]'::jsonb, 'under_review', 'claude'
