insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Promover, na via, competição, eventos organizados, exibição e demonstração de perícia em manobra de veículo, ou deles participar como condutor, sem permissão da autoridade de trânsito é infração gravíssima, com multa (dez vezes), suspensão do direito de dirigir e apreensão do veículo, e medida administrativa de recolhimento do documento e remoção do veículo. As penalidades se aplicam aos promotores e aos condutores participantes, e a multa é em dobro na reincidência em doze meses.', '["Competição ou exibição sem permissão.","Aplica-se a promotores e condutores.","Mesmas penalidades da disputa de corrida."]'::jsonb, '["Promotores E condutores participantes respondem."]'::jsonb, 'O organizador do evento de manobras sem autorização é penalizado, assim como os condutores.', '["Assertiva que isenta o promotor do evento de penalidade erra."]'::jsonb, '[]'::jsonb, '["Art. 67"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-174' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '21dd0cdcfb267c07c80d2fde3e1c103ca8f2890d225fddd13132f6feff0446cf'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Utilizar-se de veículo para demonstrar ou exibir manobra perigosa, mediante arrancada brusca, derrapagem ou frenagem com deslizamento ou arrastamento de pneus, é infração gravíssima, com multa (dez vezes), suspensão do direito de dirigir e apreensão do veículo, e medida administrativa de recolhimento do documento e remoção do veículo. A multa é em dobro na reincidência em doze meses.', '["Arrancada brusca, derrapagem ou frenagem com arrastamento.","Gravíssima, com suspensão e apreensão."]'::jsonb, '["Mesmas penalidades da disputa de corrida."]'::jsonb, 'Fazer cavalo de pau na via pública para exibição gera apreensão do veículo.', '["Assertiva que considera média a exibição de manobra perigosa erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 173"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-175' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e5c902489481ad54cac7d33e59a5b768ee76ecd62112be2a499183d991756be8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar o condutor envolvido em sinistro com vítima de prestar ou providenciar socorro, podendo fazê-lo; de adotar providências para evitar perigo ao trânsito no local; de preservar o local, de forma a facilitar os trabalhos da polícia e da perícia; de remover o veículo quando determinado pela autoridade; ou de identificar-se ao policial e prestar as informações necessárias ao boletim de ocorrência, é infração gravíssima, com multa (cinco vezes) e suspensão do direito de dirigir, e recolhimento do documento de habilitação.', '["Cinco condutas omissivas após sinistro com vítima.","Gravíssima, multa (cinco vezes) e suspensão do direito de dirigir."]'::jsonb, '["Não confundir com o crime de omissão de socorro (art. 304).","ATUALIZAÇÃO: o termo \"acidente\" foi substituído por \"sinistro\" por lei posterior."]'::jsonb, 'Quem foge do local do sinistro sem socorrer a vítima comete infração gravíssima.', '["Assertiva que classifica como média a fuga do local do sinistro com vítima erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 304"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-176' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '91a45053d30cca18bbefe2fb89c3b6b59a273bfe18a66dc3ace2a616b9e40398'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar o condutor de prestar socorro à vítima de sinistro de trânsito quando solicitado pela autoridade e seus agentes é infração grave, com penalidade de multa.', '["Infração grave.","Recusar socorro quando solicitado pela autoridade."]'::jsonb, '["Grave, diferente do art. 176 (gravíssima)."]'::jsonb, 'O condutor que se recusa a levar a vítima ao hospital a pedido do policial é multado.', '["Assertiva que classifica como gravíssima a recusa de socorro a pedido da autoridade erra: é grave."]'::jsonb, '[]'::jsonb, '["Art. 176"]'::jsonb, 'under_review', 'claude'
