insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fazer ou deixar que se faça reparo em veículo na via pública, salvo nos casos de impedimento absoluto de sua remoção e em que o veículo esteja devidamente sinalizado, é infração grave, com multa e remoção do veículo, quando em pista de rolamento de rodovias e vias de trânsito rápido, e leve, com multa, nas demais vias.', '["Reparo na via pública.","Grave em rodovias e vias de trânsito rápido.","Leve nas demais vias."]'::jsonb, '["A gravidade depende do tipo de via."]'::jsonb, 'Trocar o óleo do carro na pista da rodovia é infração grave.', '["Assertiva que classifica como leve o reparo na pista de rodovias erra: é grave."]'::jsonb, '[]'::jsonb, '["Art. 46"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-179' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9d6727eea8717d1cc843b064761e0ecf994309ea3848bcca6e8a1d44b756088a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ter seu veículo imobilizado na via por falta de combustível é infração média, com multa e a medida administrativa de remoção do veículo.', '["Infração média.","Multa e remoção do veículo."]'::jsonb, '["Média, com remoção do veículo."]'::jsonb, 'O carro parado por falta de combustível pode ser removido e gera multa.', '["Assertiva que classifica como leve a imobilização por falta de combustível erra: é média."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-180' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2ce4f949df564ed512bf454bdd8a5d0aee99ea544d7fad6dfc31de4669f1d338'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
