insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitar com o veículo na faixa ou pista da direita regulamentada como de circulação exclusiva para determinado tipo de veículo, exceto para acesso a imóveis lindeiros ou conversões à direita, é infração leve; na faixa ou pista da esquerda regulamentada como exclusiva, é infração grave; e na faixa ou via de trânsito exclusivo destinada aos veículos de transporte público coletivo, salvo força maior e autorização do poder público, é infração gravíssima, com multa e apreensão do veículo, e remoção.', '["Faixa exclusiva da direita: leve.","Faixa exclusiva da esquerda: grave.","Faixa exclusiva de transporte coletivo: gravíssima com apreensão."]'::jsonb, '["Faixa de ônibus: GRAVÍSSIMA, com apreensão e remoção."]'::jsonb, 'Dirigir na faixa exclusiva de ônibus gera multa gravíssima e apreensão do veículo.', '["Assertiva que classifica como leve o uso indevido da faixa de ônibus erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 185"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-184' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2da550b6e62e54dadc6466e744e95f5acb6eda223ca80acb08149c120b969f27'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o veículo estiver em movimento, deixar de conservá-lo na faixa a ele destinada pela sinalização de regulamentação, exceto em situações de emergência, ou deixar de conservar nas faixas da direita os veículos lentos e de maior porte, é infração média, com penalidade de multa.', '["Manter o veículo na faixa destinada.","Veículos lentos e de maior porte nas faixas da direita.","Infração média."]'::jsonb, '["Média; exceção para emergência."]'::jsonb, 'O caminhão lento deve trafegar nas faixas da direita.', '["Assertiva que permite caminhões lentos na faixa da esquerda erra."]'::jsonb, '[]'::jsonb, '["Art. 184"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-185' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2b25fd7547e0f2fe9de847bf28b9c71dfd70a20d4f917cb665722f35c920cce8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitar pela contramão de direção em vias com duplo sentido de circulação, exceto para ultrapassar outro veículo e apenas pelo tempo necessário, respeitada a preferência de quem vem em sentido contrário, é infração grave, com multa. Transitar pela contramão em vias com sinalização de sentido único de circulação é infração gravíssima, com multa.', '["Duplo sentido: grave.","Sentido único: gravíssima."]'::jsonb, '["Via de sentido ÚNICO: gravíssima; via de duplo sentido: grave."]'::jsonb, 'Entrar na contramão de uma rua de mão única é infração gravíssima.', '["Assertiva que classifica como grave a contramão em via de sentido único erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-186' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '873f0db3fffa36df44d2a979ff34f79ffa1af23ede8637846d579f316f986219'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
