insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitar em locais e horários não permitidos pela regulamentação estabelecida pela autoridade competente é infração média, com multa, quando se trata de todos os tipos de veículos. O artigo traz ainda inciso específico para determinados veículos, cuja redação consta do texto oficial.', '["Locais e horários não permitidos pela regulamentação.","Todos os tipos de veículos: média."]'::jsonb, '["Média para todos os veículos; confira no texto oficial o inciso específico."]'::jsonb, 'Circular em área restrita fora do horário permitido gera multa média.', '["Assertiva que classifica como leve a circulação em local e horário proibidos erra: é média."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-187' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '69f3c1f01cb93c4db182ca5dd098d4a4cf73a607d98566640ef8636eacdfd621'
