select u.id, u.content_sha256, 'Transitar ao lado de outro veículo, interrompendo ou perturbando o trânsito, é infração média, com penalidade de multa.', '["Infração média.","Transitar lado a lado perturbando o fluxo."]'::jsonb, '["Média."]'::jsonb, 'Dois carros lado a lado que bloqueiam a via cometem a infração.', '["Assertiva que classifica como gravíssima a circulação lado a lado erra: é média."]'::jsonb, '[]'::jsonb, '["Art. 185"]'::jsonb, 'under_review', 'claude'
